/* GENERATED by build.mjs from src/bootstrap/*.java -- do not edit.
 *
 * The worker writes these into CheerpJ's /str/ mount and compiles them on first
 * load(). Edit the .java files and re-run `node build.mjs`; `npm run check`
 * fails if this file is stale.
 */

export const BOOTSTRAP_SOURCES: Record<string, string> = {
  "Bridge.java": "package warsha;\n\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStream;\nimport java.io.PrintStream;\nimport java.io.UnsupportedEncodingException;\n\n/**\n * The JS <-> Java bridge. Every native here is implemented in jvm.worker.js as\n * Java_warsha_Bridge_<name>; CheerpJ awaits async natives, so a native that\n * returns a pending promise genuinely parks the Java thread.\n *\n * Nothing in this class may call System.exit(). One CheerpJ JVM serves many\n * runs (the worker is reused), and exiting it would strand every later run in\n * the same session. Status is reported through natives instead.\n */\npublic class Bridge {\n\n    /** Blocks until the UI submits a line. Returns null for EOF. */\n    public static native String readLine();\n\n    /** Program output. One call per write, no buffering -- see installStdout. */\n    public static native void writeOut(String s);\n\n    public static native void writeErr(String s);\n\n    /**\n     * Compiler output. A separate channel from writeErr so the runtime can\n     * rewrite compiler paths without touching anything the program printed.\n     */\n    public static native void writeDiag(String s);\n\n    /**\n     * Terminal status of a bootstrap phase. `phase` is \"compile\" or \"run\",\n     * `code` is \"0\" for success or a non-zero exit code. Reported through a\n     * native rather than a process exit code, because a real exit would kill\n     * the shared JVM.\n     */\n    public static native void phaseDone(String phase, String code);\n\n    public static void installStdin() {\n        System.setIn(new InputStream() {\n            private byte[] buf = new byte[0];\n            private int pos = 0;\n            private boolean eof = false;\n\n            /** True if a byte is available; false at end of input. */\n            private boolean fill() throws IOException {\n                while (pos >= buf.length) {\n                    if (eof) return false;\n                    String line = readLine();\n                    if (line == null) {\n                        eof = true;\n                        return false;\n                    }\n                    buf = (line + \"\\n\").getBytes(\"UTF-8\");\n                    pos = 0;\n                }\n                return true;\n            }\n\n            @Override\n            public int read() throws IOException {\n                if (!fill()) return -1;\n                return buf[pos++] & 0xFF;\n            }\n\n            /**\n             * MUST be overridden. InputStream's default bulk read loops on\n             * read() until it has len bytes or hits EOF, so Scanner's 1024-byte\n             * request would keep asking the student for more lines and the\n             * program would never advance past its first prompt. Returning only\n             * what is already buffered is the real console semantic.\n             */\n            @Override\n            public int read(byte[] b, int off, int len) throws IOException {\n                if (len == 0) return 0;\n                if (!fill()) return -1;\n                int n = Math.min(len, buf.length - pos);\n                System.arraycopy(buf, pos, b, off, n);\n                pos += n;\n                return n;\n            }\n\n            @Override\n            public int available() {\n                return buf.length - pos;\n            }\n        });\n    }\n\n    /**\n     * A worker has no DOM, so CheerpJ's #console element trick is unavailable.\n     * Re-pointing the streams at natives is better anyway: it gives real\n     * out/err separation and lets us control flushing precisely.\n     */\n    public static void installStdout() throws UnsupportedEncodingException {\n        System.setOut(new PrintStream(new NativeOut(false), true, \"UTF-8\"));\n        System.setErr(new PrintStream(new NativeOut(true), true, \"UTF-8\"));\n    }\n\n    /**\n     * Unbuffered on purpose, and load-bearing for the acceptance criterion that\n     * a student sees `System.out.print(\"Name: \")` before the following\n     * nextLine() blocks. PrintStream's autoflush only triggers on a newline, so\n     * a partial-line prompt would otherwise sit in the buffer until the next\n     * println -- which usually arrives after the read has already returned, and\n     * the student types blind.\n     *\n     * If anyone ever wraps this in a BufferedOutputStream for throughput, they\n     * must flush before every blocking read or that criterion regresses\n     * silently. The harness has a test for exactly this.\n     */\n    private static final class NativeOut extends OutputStream {\n        private final boolean err;\n        /** Bytes of a multi-byte character that has not arrived in full yet. */\n        private byte[] partial = new byte[0];\n\n        NativeOut(boolean err) {\n            this.err = err;\n        }\n\n        /**\n         * PrintStream reaches this only for a raw System.out.write(int); text\n         * goes through the byte-array path below. A single byte of a multi-byte\n         * character cannot be decoded on its own, so hold it until the sequence\n         * completes rather than emitting a replacement character.\n         */\n        @Override\n        public void write(int b) {\n            byte[] next = new byte[partial.length + 1];\n            System.arraycopy(partial, 0, next, 0, partial.length);\n            next[partial.length] = (byte) b;\n            int hold = incompleteTail(next, next.length);\n            emit(next, 0, next.length - hold);\n            partial = new byte[hold];\n            System.arraycopy(next, next.length - hold, partial, 0, hold);\n        }\n\n        /**\n         * OutputStreamWriter never splits one character across two calls, so\n         * whatever arrives here decodes cleanly on its own.\n         */\n        @Override\n        public void write(byte[] b, int off, int len) {\n            if (len == 0) return;\n            if (partial.length > 0) {\n                write(b[off] & 0xFF);\n                off++;\n                len--;\n                if (len == 0) return;\n            }\n            emit(b, off, len);\n        }\n\n        private void emit(byte[] b, int off, int len) {\n            if (len <= 0) return;\n            String s;\n            try {\n                s = new String(b, off, len, \"UTF-8\");\n            } catch (UnsupportedEncodingException e) {\n                s = new String(b, off, len);\n            }\n            if (s.isEmpty()) return;\n            if (err) writeErr(s);\n            else writeOut(s);\n        }\n\n        /** Length of the trailing bytes that form a started-but-unfinished character. */\n        private static int incompleteTail(byte[] b, int len) {\n            // Walk back over continuation bytes (10xxxxxx) to the lead byte.\n            int i = len - 1;\n            int continuations = 0;\n            while (i >= 0 && (b[i] & 0xC0) == 0x80) {\n                continuations++;\n                i--;\n            }\n            if (i < 0) return 0; // all continuations: not something we produced\n            int lead = b[i] & 0xFF;\n            int expected;\n            if (lead < 0x80) expected = 1;\n            else if ((lead & 0xE0) == 0xC0) expected = 2;\n            else if ((lead & 0xF0) == 0xE0) expected = 3;\n            else if ((lead & 0xF8) == 0xF0) expected = 4;\n            else return 0; // invalid lead byte; let the decoder deal with it\n            int have = continuations + 1;\n            return have < expected ? have : 0;\n        }\n    }\n}\n",
  "Build.java": "package warsha;\n\nimport java.io.BufferedReader;\nimport java.io.File;\nimport java.io.FileOutputStream;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.io.PrintWriter;\nimport java.io.StringWriter;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.regex.Matcher;\nimport java.util.regex.Pattern;\n\nimport org.eclipse.jdt.core.compiler.batch.BatchCompiler;\n\n/**\n * Stages the student's sources and compiles them.\n *\n * Two constraints of CheerpJ's filesystem shape this class, both measured\n * rather than documented anywhere:\n *\n *  1. /str/ -- the only mount JS can write -- is a FLAT namespace. Writing\n *     \"/str/models/Person.java\" appears to succeed but Java cannot open it, and\n *     writing everything flat breaks the moment a project has models/Item.java\n *     and app/Item.java. So JS writes each source under an opaque unique name\n *     and lists the real relative paths in a manifest; this class replays that\n *     manifest into a real directory tree under /files/, which Java *can* mkdir.\n *\n *  2. The compiler will not create its own -d directory, and /files/ is\n *     read-only from JS. Only Java can prepare it, which is the other half of\n *     why this class exists.\n *\n * The tree is per-run (/files/warsha-run-<runId>/) rather than a fixed path that gets\n * wiped. IndexedDB backs /files/, so a stale .class from an earlier run can\n * make a broken project look like it still works; a fresh directory makes that\n * structurally impossible instead of relying on a delete that we would have to\n * trust. Older run directories are removed on a best-effort basis afterwards.\n *\n * Never calls System.exit -- see Bridge.\n */\npublic class Build {\n\n    /**\n     * Where a run's staged sources and .class output live.\n     *\n     * The prefix is deliberately distinctive. /files/ is shared with anything\n     * else Warsha may one day persist there, and gcOldRuns deletes directories\n     * it believes are old runs -- a loose prefix like \"r\" would happily eat a\n     * future /files/results.\n     */\n    private static final String RUN_PREFIX = \"warsha-run-\";\n\n    /** Matches exactly what runDir produces, and nothing else. */\n    private static final Pattern RUN_DIR = Pattern.compile(\"^\" + RUN_PREFIX + \"[A-Za-z0-9]+$\");\n\n    static File runDir(String runId) {\n        return new File(\"/files/\" + RUN_PREFIX + runId);\n    }\n\n    static File srcDir(String runId) {\n        return new File(runDir(runId), \"src\");\n    }\n\n    static File outDir(String runId) {\n        return new File(runDir(runId), \"out\");\n    }\n\n    /** Written by this class, read by Launcher: the entry's fully-qualified name. */\n    static File mainClassFile(String runId) {\n        return new File(runDir(runId), \"main.txt\");\n    }\n\n    /**\n     * Written by this class, read by Traces: \"&lt;binary name&gt;\\t&lt;source file&gt;\"\n     * for every top-level type in the project.\n     *\n     * This is the SourceFile attribute that CheerpJ's stack walker refuses to\n     * give back, rebuilt from the only place that still knows\n     * it -- the sources, while we have them in hand.\n     */\n    static File sourceIndexFile(String runId) {\n        return new File(runDir(runId), \"classes.tsv\");\n    }\n\n    private static boolean visitedBefore = false;\n\n    public static void main(String[] args) {\n        String runId = args[0];\n        String entryPath = args[1];\n        long t0 = System.currentTimeMillis();\n        System.out.println(\"warsha-probe: visitedBefore=\" + visitedBefore);\n        visitedBefore = true;\n        try {\n            Bridge.phaseDone(\"compile\", String.valueOf(build(runId, entryPath)));\n            System.out.println(\"warsha-probe: build total \" + (System.currentTimeMillis() - t0) + \"ms\");\n        } catch (Throwable t) {\n            // A failure here is ours, not the student's; label it as such.\n            StringWriter sw = new StringWriter();\n            t.printStackTrace(new PrintWriter(sw));\n            Bridge.writeDiag(\"warsha: internal build failure\\n\" + sw);\n            Bridge.phaseDone(\"compile\", \"70\");\n        }\n    }\n\n    /** Returns 0 on success, 1 if the student's code did not compile. */\n    private static int build(String runId, String entryPath) throws IOException {\n        long t0 = System.currentTimeMillis();\n        gcOldRuns(runId);\n        long t1 = System.currentTimeMillis();\n        System.out.println(\"warsha-probe: gc \" + (t1 - t0) + \"ms\");\n\n        File src = srcDir(runId);\n        File out = outDir(runId);\n        if (!src.mkdirs() && !src.isDirectory()) throw new IOException(\"cannot create \" + src);\n        if (!out.mkdirs() && !out.isDirectory()) throw new IOException(\"cannot create \" + out);\n\n        List<String[]> manifest = readManifest(runId);\n        List<String> sourcePaths = new ArrayList<String>();\n        StringBuilder sourceIndex = new StringBuilder();\n        String entrySource = null;\n\n        for (String[] entry : manifest) {\n            String flatName = entry[0];\n            String relativePath = entry[1];\n            String content = readAll(new File(\"/str/\" + flatName));\n\n            File target = new File(src, relativePath);\n            File parent = target.getParentFile();\n            if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {\n                throw new IOException(\"cannot create \" + parent);\n            }\n            writeAll(target, content);\n            sourcePaths.add(target.getPath());\n            indexTypes(sourceIndex, relativePath, content);\n\n            if (relativePath.equals(entryPath)) entrySource = content;\n        }\n\n        if (entrySource == null) throw new IOException(\"entry \" + entryPath + \" not in the manifest\");\n        writeAll(mainClassFile(runId), mainClassOf(entryPath, entrySource));\n        writeAll(sourceIndexFile(runId), sourceIndex.toString());\n        long t2 = System.currentTimeMillis();\n        System.out.println(\"warsha-probe: stage \" + (t2 - t0) + \"ms\");\n\n        int result = compile(sourcePaths, out) ? 0 : 1;\n        System.out.println(\"warsha-probe: ecj \" + (System.currentTimeMillis() - t2) + \"ms\");\n        return result;\n    }\n\n    /**\n     * Invokes ECJ through its documented programmatic entry point rather than\n     * its main(). Going through main() means diagnostics land on the JS console\n     * (a worker has no #console element for CheerpJ to write into), which then\n     * has to be scraped and de-noised. Here the diagnostics come back in a\n     * writer we own, and CheerpJ's own console chatter stays where it is.\n     */\n    private static boolean compile(List<String> sourcePaths, File out) {\n        List<String> argv = new ArrayList<String>(sourcePaths);\n        argv.add(\"-d\");\n        argv.add(out.getPath());\n        argv.add(\"-1.8\");           // CheerpJ's runtime is Java 8; see INTEGRATION.md\n        argv.add(\"-g\");             // buys no line numbers under CheerpJ, but is correct\n        argv.add(\"-encoding\");\n        argv.add(\"UTF-8\");\n        argv.add(\"-proc:none\");     // no annotation processing\n        argv.add(\"-nowarn\");        // beginners do not need ECJ's warnings\n\n        StringWriter outText = new StringWriter();\n        StringWriter errText = new StringWriter();\n        PrintWriter outWriter = new PrintWriter(outText);\n        PrintWriter errWriter = new PrintWriter(errText);\n\n        boolean ok = BatchCompiler.compile(\n                argv.toArray(new String[argv.size()]), outWriter, errWriter, null);\n\n        outWriter.flush();\n        errWriter.flush();\n        String diagnostics = errText.toString();\n        if (diagnostics.isEmpty()) diagnostics = outText.toString();\n        if (!diagnostics.isEmpty()) Bridge.writeDiag(diagnostics);\n        return ok;\n    }\n\n    // --- the entry class's real name -----------------------------------------\n\n    private static final Pattern PACKAGE =\n            Pattern.compile(\"^\\\\s*package\\\\s+([A-Za-z_$][A-Za-z0-9_$]*(?:\\\\s*\\\\.\\\\s*[A-Za-z_$][A-Za-z0-9_$]*)*)\\\\s*;\",\n                    Pattern.MULTILINE);\n\n    /**\n     * \"app/Main.java\" + \"package app;\" -> \"app.Main\".\n     *\n     * Derived from the package declaration rather than from the directory,\n     * because the two need not agree: the compiler only insists that a public\n     * class match its *file name*. A student whose file sits at the project\n     * root with `package app;` at the top still gets a class the launcher can\n     * find.\n     */\n    static String mainClassOf(String entryPath, String source) {\n        String fileName = simpleFileName(entryPath);\n        if (fileName.endsWith(\".java\")) fileName = fileName.substring(0, fileName.length() - 5);\n        String pkg = packageOf(source);\n        return pkg.isEmpty() ? fileName : pkg + \".\" + fileName;\n    }\n\n    /** The declared package, or \"\" for the default package. */\n    static String packageOf(String source) {\n        Matcher m = PACKAGE.matcher(blankNonCode(source));\n        if (!m.find()) return \"\";\n        return m.group(1).replaceAll(\"\\\\s+\", \"\");\n    }\n\n    private static String simpleFileName(String path) {\n        int slash = path.lastIndexOf('/');\n        return slash >= 0 ? path.substring(slash + 1) : path;\n    }\n\n    // --- the class -> source-file index --------------------------------------\n\n    /**\n     * Appends \"&lt;binary name&gt;\\t&lt;file&gt;\" for every top-level type in one source.\n     *\n     * Every type gets a line, not just the public one, because javac records\n     * the FILE in each class's SourceFile attribute: a package-private\n     * `class Circle` declared in Shapes.java belongs to Shapes.java, and a\n     * trace that claimed \"Circle.java\" would send a student looking for a file\n     * that does not exist. Inner classes need no entries -- Traces strips\n     * everything from the '$' on before looking a frame up.\n     */\n    static void indexTypes(StringBuilder into, String relativePath, String source) {\n        String pkg = packageOf(source);\n        String file = simpleFileName(relativePath);\n        for (String type : topLevelTypes(source)) {\n            into.append(pkg.isEmpty() ? type : pkg + \".\" + type).append('\\t').append(file).append('\\n');\n        }\n    }\n\n    /**\n     * The names of the types declared at the top level of a source file, in\n     * declaration order.\n     *\n     * Deliberately a scanner and not a parser: it tracks brace depth and takes\n     * the identifier after `class`, `interface` or `enum` at depth 0. Comments\n     * and literals are blanked first, so neither `// class Ghost` nor\n     * `\"}\"` can move the depth or invent a type. Anything it misses costs a\n     * frame the simple-name fallback, never a wrong compile.\n     */\n    static List<String> topLevelTypes(String source) {\n        String s = blankNonCode(source);\n        List<String> found = new ArrayList<String>();\n        int depth = 0;\n        int i = 0;\n        int n = s.length();\n        while (i < n) {\n            char c = s.charAt(i);\n            if (c == '{') {\n                depth++;\n                i++;\n            } else if (c == '}') {\n                if (depth > 0) depth--;\n                i++;\n            } else if (Character.isJavaIdentifierStart(c)\n                    && (i == 0 || !Character.isJavaIdentifierPart(s.charAt(i - 1)))) {\n                int end = i;\n                while (end < n && Character.isJavaIdentifierPart(s.charAt(end))) end++;\n                String word = s.substring(i, end);\n                if (depth == 0 && (word.equals(\"class\") || word.equals(\"interface\") || word.equals(\"enum\"))) {\n                    int start = end;\n                    while (start < n && Character.isWhitespace(s.charAt(start))) start++;\n                    int stop = start;\n                    while (stop < n && Character.isJavaIdentifierPart(s.charAt(stop))) stop++;\n                    if (stop > start) found.add(s.substring(start, stop));\n                }\n                i = end;\n            } else {\n                i++;\n            }\n        }\n        return found;\n    }\n\n    /**\n     * Comments and literals replaced by spaces; length, newlines outside block\n     * comments, and every other character left alone.\n     *\n     * Two callers need it and for different reasons: packageOf must not be\n     * fooled by a commented-out `package` line (which would stage the class\n     * under a name nothing can load, surfacing much later as an unrelated\n     * \"cannot find symbol\"), and topLevelTypes must not let a brace inside a\n     * string literal shift its depth.\n     */\n    static String blankNonCode(String source) {\n        char[] out = source.toCharArray();\n        int i = 0;\n        int n = out.length;\n        while (i < n) {\n            char c = out[i];\n            if (c == '/' && i + 1 < n && out[i + 1] == '/') {\n                while (i < n && out[i] != '\\n') out[i++] = ' ';\n            } else if (c == '/' && i + 1 < n && out[i + 1] == '*') {\n                out[i++] = ' ';\n                out[i++] = ' ';\n                while (i < n && !(out[i] == '*' && i + 1 < n && out[i + 1] == '/')) out[i++] = ' ';\n                if (i < n) out[i++] = ' ';\n                if (i < n) out[i++] = ' ';\n            } else if (c == '\"' || c == '\\'') {\n                out[i++] = ' ';\n                while (i < n && out[i] != c) {\n                    // A backslash escape consumes the next character, so a\n                    // literal quote inside the literal does not end it.\n                    if (out[i] == '\\\\' && i + 1 < n) out[i++] = ' ';\n                    if (i < n) out[i++] = ' ';\n                }\n                if (i < n) out[i++] = ' ';\n            } else {\n                i++;\n            }\n        }\n        return new String(out);\n    }\n\n    // --- manifest -------------------------------------------------------------\n\n    /** Lines of \"<flat name in /str/>\\t<relative path in the project>\". */\n    private static List<String[]> readManifest(String runId) throws IOException {\n        String text = readAll(new File(\"/str/warsha-manifest-\" + runId + \".tsv\"));\n        List<String[]> entries = new ArrayList<String[]>();\n        for (String line : text.split(\"\\n\")) {\n            if (line.isEmpty()) continue;\n            int tab = line.indexOf('\\t');\n            if (tab < 0) throw new IOException(\"malformed manifest line: \" + line);\n            entries.add(new String[] { line.substring(0, tab), line.substring(tab + 1) });\n        }\n        if (entries.isEmpty()) throw new IOException(\"empty manifest\");\n        return entries;\n    }\n\n    // --- filesystem helpers ---------------------------------------------------\n\n    private static String readAll(File file) throws IOException {\n        BufferedReader reader = new BufferedReader(\n                new InputStreamReader(new java.io.FileInputStream(file), \"UTF-8\"));\n        try {\n            StringBuilder sb = new StringBuilder();\n            char[] chunk = new char[8192];\n            int n;\n            while ((n = reader.read(chunk)) > 0) sb.append(chunk, 0, n);\n            return sb.toString();\n        } finally {\n            reader.close();\n        }\n    }\n\n    private static void writeAll(File file, String content) throws IOException {\n        FileOutputStream stream = new FileOutputStream(file);\n        try {\n            stream.write(content.getBytes(\"UTF-8\"));\n        } finally {\n            stream.close();\n        }\n    }\n\n    /**\n     * Best effort: /files/ is IndexedDB-backed and persists across sessions, so\n     * without this every run a student ever makes would accumulate there. A\n     * failure to delete is not fatal -- correctness comes from the fresh\n     * per-run directory, not from the cleanup.\n     *\n     * Whether delete() even works on CheerpJ's IndexedDB mount is not something\n     * the spike established, so the outcome is printed. During Build,\n     * System.out is still CheerpJ's own console (only Launcher redirects the\n     * streams), which the worker forwards on its internal channel -- so this\n     * line never reaches a student, and the harness can assert on it.\n     */\n    private static void gcOldRuns(String runId) {\n        File[] children = new File(\"/files\").listFiles();\n        if (children == null) {\n            System.out.println(\"warsha-gc: cannot list /files\");\n            return;\n        }\n        String keep = runDir(runId).getName();\n        int deleted = 0;\n        int failed = 0;\n        for (File child : children) {\n            String name = child.getName();\n            if (name.equals(keep) || !RUN_DIR.matcher(name).matches()) continue;\n            deleteTree(child);\n            if (child.exists()) failed++;\n            else deleted++;\n        }\n        System.out.println(\"warsha-gc: deleted=\" + deleted + \" failed=\" + failed);\n    }\n\n    private static void deleteTree(File file) {\n        File[] children = file.listFiles();\n        if (children != null) {\n            for (File child : children) deleteTree(child);\n        }\n        file.delete();\n    }\n}\n",
  "Launcher.java": "package warsha;\n\nimport java.io.BufferedReader;\nimport java.io.FileInputStream;\nimport java.io.InputStreamReader;\nimport java.lang.reflect.InvocationTargetException;\nimport java.lang.reflect.Method;\n\n/**\n * Runs the student's main method and reports what happened.\n *\n * Never calls System.exit: one CheerpJ JVM serves every run in a session, so\n * exiting would strand all later runs. The exit status goes out through\n * Bridge.phaseDone instead.\n *\n * Uncaught throwables are rendered by Traces, in Java, where frames are still\n * structured objects. Doing it here rather than by pattern-matching text in JS\n * is what makes \"Exception in thread ...\" identical to a real JVM's: the\n * message restoration and the \"... N more\" collapsing both need the object\n * graph, not the string.\n */\npublic class Launcher {\n\n    /**\n     * The name a real JVM prints for the thread running main.\n     *\n     * Hardcoded rather than read from Thread.currentThread(): CheerpJ runs\n     * cheerpjRunMain on a thread of its own choosing and we are not going to\n     * show a student \"Exception in thread \"cheerpj-1\"\" for their own main\n     * method. Threads the student starts themselves report their real names --\n     * those go through the default handler installed below.\n     */\n    private static final String MAIN_THREAD = \"main\";\n\n    public static void main(String[] args) {\n        String runId = args[0];\n        String[] programArgs = new String[Math.max(0, args.length - 1)];\n        if (args.length > 1) System.arraycopy(args, 1, programArgs, 0, programArgs.length);\n\n        int status = 0;\n        try {\n            Bridge.installStdout();\n            Bridge.installStdin();\n        } catch (Throwable t) {\n            Bridge.writeDiag(\"warsha: could not install the console streams: \" + t);\n            Bridge.phaseDone(\"run\", \"70\");\n            return;\n        }\n\n        final Traces traces = Traces.forRun(runId);\n        installThreadHandler(traces);\n\n        try {\n            String mainClass = readMainClass(runId);\n            Method main = Class.forName(mainClass).getMethod(\"main\", String[].class);\n            try {\n                main.invoke(null, (Object) programArgs);\n            } catch (InvocationTargetException e) {\n                Throwable cause = e.getCause() == null ? e : e.getCause();\n                System.err.print(traces.format(cause, MAIN_THREAD));\n                status = 1;\n            }\n        } catch (ClassNotFoundException e) {\n            System.err.println(\"Error: could not find or load main class \" + e.getMessage());\n            status = 1;\n        } catch (NoSuchMethodException e) {\n            System.err.println(\"Error: no main method found. A Java program starts with:\");\n            System.err.println(\"    public static void main(String[] args)\");\n            status = 1;\n        } catch (Throwable t) {\n            System.err.print(traces.format(t, MAIN_THREAD));\n            status = 1;\n        }\n\n        System.out.flush();\n        System.err.flush();\n        Bridge.phaseDone(\"run\", String.valueOf(status));\n    }\n\n    /**\n     * Makes an exception on a thread the student started look like one on main.\n     *\n     * Without this the JVM's own handler prints the trace, which under CheerpJ\n     * means bare \"(Unknown Source)\" frames and no \"/ by zero\" -- the output this\n     * class exists to replace. It reports the thread's real name, as java does.\n     *\n     * Guarded: if CheerpJ ever refuses the call, a single-threaded program\n     * (which is all the curriculum has) must not lose its own trace over it.\n     */\n    private static void installThreadHandler(final Traces traces) {\n        try {\n            Thread.setDefaultUncaughtExceptionHandler(new Thread.UncaughtExceptionHandler() {\n                @Override\n                public void uncaughtException(Thread thread, Throwable problem) {\n                    System.err.print(traces.format(problem, thread.getName()));\n                    System.err.flush();\n                }\n            });\n        } catch (Throwable ignored) {\n            // The main path below does not depend on this.\n        }\n    }\n\n    private static String readMainClass(String runId) throws java.io.IOException {\n        BufferedReader reader = new BufferedReader(\n                new InputStreamReader(new FileInputStream(Build.mainClassFile(runId)), \"UTF-8\"));\n        try {\n            String line = reader.readLine();\n            if (line == null || line.trim().isEmpty()) throw new java.io.IOException(\"no main class recorded\");\n            return line.trim();\n        } finally {\n            reader.close();\n        }\n    }\n}\n",
  "Traces.java": "package warsha;\n\nimport java.io.BufferedReader;\nimport java.io.FileInputStream;\nimport java.io.InputStreamReader;\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.IdentityHashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/**\n * Renders an uncaught throwable the way a real JVM does.\n *\n * The target is what `java` prints for classes carrying no line-number table,\n * character for character:\n *\n * <pre>\n * Exception in thread \"main\" java.lang.ArithmeticException: / by zero\n * \tat app.Main.main(Main.java)\n * </pre>\n *\n * Two things CheerpJ withholds have to be worked around. Both were measured\n * directly rather than read anywhere, and neither is a compiler flag we are\n * missing -- compiling with -g changes nothing:\n *\n *  1. Every frame reports getFileName() == null and getLineNumber() == 0,\n *     whatever the compiler was told. The file name is therefore reconstructed\n *     from an index Build writes; the line number is simply absent, exactly as\n *     it is for a real -g:none class. That is why frames end in \"(Main.java)\"\n *     and not \"(Main.java:12)\" -- both are shapes real java prints, so a\n *     student never sees an apology or a Warsha-ism.\n *  2. Implicitly thrown exceptions arrive with getMessage() == null, where a\n *     real JVM supplies one. Exactly one restoration is safe; see\n *     restoredMessage.\n *\n * The nesting, the \"... N more\" collapsing and the circular-reference guard\n * follow java.lang.Throwable.printStackTrace step for step, so a cause chain\n * reads the same here as it does in a terminal.\n */\nfinal class Traces {\n\n    /** Top-level binary name (\"models.Person\") -> source file (\"Person.java\"). */\n    private final Map<String, String> sourceFiles;\n\n    Traces(Map<String, String> sourceFiles) {\n        this.sourceFiles = sourceFiles;\n    }\n\n    /**\n     * Loads the class -> source-file index Build wrote for this run.\n     *\n     * Never throws: without the index every frame falls back to\n     * &lt;SimpleName&gt;.java, which is already correct for the one-public-class-\n     * per-file shape that almost all student code has.\n     */\n    static Traces forRun(String runId) {\n        Map<String, String> index = new HashMap<String, String>();\n        try {\n            BufferedReader reader = new BufferedReader(new InputStreamReader(\n                    new FileInputStream(Build.sourceIndexFile(runId)), \"UTF-8\"));\n            try {\n                String line;\n                while ((line = reader.readLine()) != null) {\n                    int tab = line.indexOf('\\t');\n                    if (tab > 0) index.put(line.substring(0, tab), line.substring(tab + 1));\n                }\n            } finally {\n                reader.close();\n            }\n        } catch (Throwable ignored) {\n            // Fall back to simple names rather than lose the whole trace.\n        }\n        return new Traces(index);\n    }\n\n    // --- the whole block a student sees --------------------------------------\n\n    /**\n     * The complete uncaught-exception report, newline-terminated, ready for\n     * System.err.print. `threadName` names the thread the throwable escaped\n     * from -- \"main\" for the student's own main method.\n     */\n    String format(Throwable t, String threadName) {\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"Exception in thread \\\"\").append(threadName).append(\"\\\" \");\n\n        Map<Throwable, Boolean> seen = new IdentityHashMap<Throwable, Boolean>();\n        seen.put(t, Boolean.TRUE);\n\n        List<StackTraceElement> frames = studentFrames(t.getStackTrace());\n        sb.append(header(t)).append('\\n');\n        for (StackTraceElement frame : frames) {\n            sb.append(\"\\tat \").append(frameText(frame)).append('\\n');\n        }\n        appendEnclosed(sb, t, frames, \"\", seen);\n        return sb.toString();\n    }\n\n    /** Suppressed exceptions then the cause: Throwable's own order. */\n    private void appendEnclosed(StringBuilder sb, Throwable t, List<StackTraceElement> frames,\n                                String prefix, Map<Throwable, Boolean> seen) {\n        for (Throwable suppressed : t.getSuppressed()) {\n            appendNested(sb, suppressed, frames, \"Suppressed: \", prefix + \"\\t\", seen);\n        }\n        Throwable cause = t.getCause();\n        if (cause != null) appendNested(sb, cause, frames, \"Caused by: \", prefix, seen);\n    }\n\n    /**\n     * One nested throwable, with the frames it shares with its enclosing trace\n     * collapsed into \"... N more\".\n     *\n     * The comparison runs over the FILTERED traces, not the raw ones, so the\n     * count matches the frames actually on screen. Frames are compared on class\n     * and method alone: CheerpJ's file and line are null/0 for everything, so\n     * StackTraceElement.equals would compare two fields that carry no\n     * information anyway.\n     */\n    private void appendNested(StringBuilder sb, Throwable t, List<StackTraceElement> enclosing,\n                              String caption, String prefix, Map<Throwable, Boolean> seen) {\n        if (seen.containsKey(t)) {\n            sb.append(prefix).append(caption)\n              .append(\"[CIRCULAR REFERENCE: \").append(header(t)).append(\"]\").append('\\n');\n            return;\n        }\n        seen.put(t, Boolean.TRUE);\n\n        List<StackTraceElement> frames = studentFrames(t.getStackTrace());\n        int mine = frames.size() - 1;\n        int theirs = enclosing.size() - 1;\n        while (mine >= 0 && theirs >= 0 && sameFrame(frames.get(mine), enclosing.get(theirs))) {\n            mine--;\n            theirs--;\n        }\n        int inCommon = frames.size() - 1 - mine;\n\n        sb.append(prefix).append(caption).append(header(t)).append('\\n');\n        for (int i = 0; i <= mine; i++) {\n            sb.append(prefix).append(\"\\tat \").append(frameText(frames.get(i))).append('\\n');\n        }\n        if (inCommon != 0) {\n            sb.append(prefix).append(\"\\t... \").append(inCommon).append(\" more\").append('\\n');\n        }\n\n        appendEnclosed(sb, t, frames, prefix, seen);\n    }\n\n    private static boolean sameFrame(StackTraceElement a, StackTraceElement b) {\n        return a.getClassName().equals(b.getClassName())\n                && a.getMethodName().equals(b.getMethodName());\n    }\n\n    // --- the first line ------------------------------------------------------\n\n    /** \"java.lang.ArithmeticException: / by zero\", or just the class name. */\n    static String header(Throwable t) {\n        String restored = restoredMessage(t);\n        if (restored != null) return t.getClass().getName() + \": \" + restored;\n        try {\n            // toString(), not getName() + getMessage(): a student who overrode\n            // toString() on their own exception class should see their version,\n            // which is what a real JVM prints.\n            String text = t.toString();\n            if (text != null) return text;\n        } catch (Throwable broken) {\n            // Their toString() threw. A real JVM would propagate; printing\n            // which exception ended the program is more use to a beginner.\n        }\n        return t.getClass().getName();\n    }\n\n    /**\n     * The message a real JVM would have carried, where that is deterministic.\n     *\n     * CheerpJ drops the message on every implicitly thrown exception, so\n     * \"java.lang.ArithmeticException\" reaches us bare where a terminal shows\n     * \"java.lang.ArithmeticException: / by zero\". Exactly one case can be\n     * restored without guessing: the VM throws a message-less\n     * ArithmeticException for integer division and remainder and for nothing\n     * else, and real java says \"/ by zero\" for BOTH `/` and `%`.\n     *\n     * Nothing else is invented. A NullPointerException stays bare -- that is\n     * not a compromise, it is what every JVM before 14 printed. Library\n     * ArithmeticExceptions (BigDecimal's \"Division by zero\", Math.addExact's\n     * \"long overflow\") are thrown from Java code, so their messages survive\n     * CheerpJ and are returned by the getMessage() check below before this rule\n     * is reached.\n     *\n     * The class is matched EXACTLY. A student's `class TooSmall extends\n     * ArithmeticException` must not be handed a message it never had.\n     */\n    static String restoredMessage(Throwable t) {\n        if (t.getMessage() != null) return null;\n        if (t.getClass() == ArithmeticException.class) return \"/ by zero\";\n        return null;\n    }\n\n    // --- frames --------------------------------------------------------------\n\n    String frameText(StackTraceElement frame) {\n        return frame.getClassName() + \".\" + frame.getMethodName()\n                + \"(\" + sourceFileFor(frame.getClassName()) + \")\";\n    }\n\n    /**\n     * The file a class was declared in.\n     *\n     * Inner, local, anonymous and lambda classes all live in their outer\n     * class's file, so everything from the first '$' on is dropped --\n     * \"app.Main$Helper\" and \"app.Main$$Lambda$1\" both resolve through\n     * \"app.Main\". Build's index then gives the real file name, which is the\n     * only way to get \"models/Shapes.java\" right for a second, non-public class\n     * declared there. Classes outside the project -- JDK frames sitting above\n     * student code -- fall back to the simple name, which is what javac records\n     * for them anyway.\n     */\n    String sourceFileFor(String className) {\n        String topLevel = className;\n        int dollar = topLevel.indexOf('$');\n        if (dollar >= 0) topLevel = topLevel.substring(0, dollar);\n\n        String known = sourceFiles.get(topLevel);\n        if (known != null) return known;\n\n        int dot = topLevel.lastIndexOf('.');\n        String simple = dot >= 0 ? topLevel.substring(dot + 1) : topLevel;\n        return simple.isEmpty() ? \"Unknown Source\" : simple + \".java\";\n    }\n\n    /**\n     * Frames that are ours or the reflection plumbing we use to reach main().\n     * Launcher invokes the student's main reflectively, so every uncaught\n     * exception arrives with four frames the student cannot act on: three\n     * reflection frames and warsha.Launcher itself. Switching to a\n     * URLClassLoader would not help -- reaching main() still needs reflection --\n     * so they get filtered rather than eliminated.\n     */\n    private static boolean isInfrastructure(String className) {\n        return className.startsWith(\"warsha.\")\n                || className.startsWith(\"sun.reflect.\")\n                || className.startsWith(\"jdk.internal.reflect.\")\n                || className.startsWith(\"java.lang.reflect.\");\n    }\n\n    /** Runtime library classes: kept when they sit above student code, never below it. */\n    private static boolean isPlatform(String className) {\n        return className.startsWith(\"java.\")\n                || className.startsWith(\"javax.\")\n                || className.startsWith(\"sun.\")\n                || className.startsWith(\"com.sun.\")\n                || className.startsWith(\"jdk.\");\n    }\n\n    /**\n     * Drops infrastructure frames, then everything below the deepest frame that\n     * is actually the student's. Platform frames above student code survive --\n     * \"at java.lang.Integer.parseInt\" is the useful part of a bad-input crash.\n     */\n    static List<StackTraceElement> studentFrames(StackTraceElement[] frames) {\n        List<StackTraceElement> kept = new ArrayList<StackTraceElement>();\n        for (StackTraceElement frame : frames) {\n            if (!isInfrastructure(frame.getClassName())) kept.add(frame);\n        }\n        int lastStudent = -1;\n        for (int i = 0; i < kept.size(); i++) {\n            if (!isPlatform(kept.get(i).getClassName())) lastStudent = i;\n        }\n        // No student frame at all (a crash entirely inside the library): keep\n        // what is left rather than showing an exception with no location.\n        if (lastStudent < 0) return kept;\n        return kept.subList(0, lastStudent + 1);\n    }\n}\n"
}
